class Solution:
    def crackSafe(self, n: int, k: int) -> str:
        passwords = []
        for i in range(k):
            for j in range(k):
                password = ""
                for _ in range(n):
                    password += str(i + 1)
                passwords.append(password)
        return max(passwords)
